<?php
session_start();require __DIR__.'/db.php';require __DIR__.'/helpers.php';checkCsrf();
if($_SERVER['REQUEST_METHOD']==='POST') { try { $rid=(int)($_POST['reservation_id']??0);$id=(int)($_POST['linked_id']??0);$kind=$_POST['kind']??'';$op=$_POST['op']??'';if($rid<1||$id<1)throw new RuntimeException('Choose a reservation and a linked record.');if(!in_array($kind,['payment','leg'],true)||!in_array($op,['add','remove'],true))throw new RuntimeException('Invalid link action.');$linkTable=$kind==='payment'?'reservation_payment':'reservation_leg';$col=$kind==='payment'?'payment_id':'leg_id';if($op==='add'){$stmt=$pdo->prepare("INSERT INTO `$linkTable` (reservation_id, `$col`) VALUES (?, ?)");$stmt->execute([$rid,$id]);flash(ucfirst($kind).' linked to reservation.');}else{$stmt=$pdo->prepare("DELETE FROM `$linkTable` WHERE reservation_id=? AND `$col`=?");$stmt->execute([$rid,$id]);flash($stmt->rowCount()?'Link removed. The linked record was not deleted.':'That link did not exist.','error');}}catch(Throwable $e){flash($e instanceof PDOException?'Could not change link. Check that both records exist and that this link is not already present.':$e->getMessage(),'error');}go('relations.php');}
$reservations=$pdo->query("SELECT r.reservation_id, CONCAT('Reservation #',r.reservation_id,' — ',p.first_name,' ',p.last_name) label FROM reservation r JOIN passenger p ON p.passenger_id=r.passenger_id ORDER BY r.reservation_id DESC")->fetchAll();$payments=$pdo->query('SELECT payment_id,payment_status_code,payment_amount FROM payment ORDER BY payment_id DESC')->fetchAll();$legs=$pdo->query('SELECT l.leg_id,l.flight_number,l.origin_airport_code,l.destination_airport_code FROM flight_leg l ORDER BY l.leg_id DESC')->fetchAll();$links=$pdo->query('SELECT rp.reservation_id,rp.payment_id,p.payment_status_code,p.payment_amount FROM reservation_payment rp JOIN payment p ON p.payment_id=rp.payment_id ORDER BY rp.reservation_id DESC')->fetchAll();$legLinks=$pdo->query('SELECT rl.reservation_id,rl.leg_id,l.flight_number,l.origin_airport_code,l.destination_airport_code FROM reservation_leg rl JOIN flight_leg l ON l.leg_id=rl.leg_id ORDER BY rl.reservation_id DESC')->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reservation Links · HarborWing</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php">✈ HarborWing Air</a><span>Reservation Management</span></header><div class="layout"><aside><h3>Modules</h3><a class="navlink" href="index.php">Dashboard</a><a class="navlink" href="reservation_details.php">Reservation Details</a><a class="navlink active" href="relations.php">Reservation Links</a></aside><main><?php showFlash();?><div class="pagehead"><div><p class="eyebrow">RELATIONSHIPS</p><h1>Reservation Links</h1><p>Add or remove a link without deleting its payment or flight leg.</p></div></div><section class="panel"><h2>Manage a link</h2><form method="post" class="formgrid"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><label>Reservation<select name="reservation_id" required><option value="">Choose reservation...</option><?php foreach($reservations as $r):?><option value="<?=e($r['reservation_id'])?>"><?=e($r['label'])?></option><?php endforeach;?></select></label><label>Link type<select name="kind" id="kind" required><option value="payment">Payment</option><option value="leg">Flight leg</option></select></label><label class="wide">Payment or flight leg<select name="linked_id" id="linked_id" required><option value="">Choose a record...</option><?php foreach($payments as $p):?><option data-kind="payment" value="<?=e($p['payment_id'])?>">Payment #<?=e($p['payment_id'])?> — <?=e($p['payment_status_code'])?> — <?=e($p['payment_amount'])?></option><?php endforeach;foreach($legs as $l):?><option data-kind="leg" value="<?=e($l['leg_id'])?>">Leg #<?=e($l['leg_id'])?> — <?=e($l['flight_number'])?> (<?=e($l['origin_airport_code'])?> → <?=e($l['destination_airport_code'])?>)</option><?php endforeach;?></select></label><label>Action<select name="op"><option value="add">Add link</option><option value="remove">Remove link only</option></select></label><div class="wide"><button class="button">Apply link change</button></div></form></section><section class="panel"><h2>Current payment links</h2><div class="tablewrap"><table><thead><tr><th>Reservation</th><th>Payment</th><th>Status</th><th>Amount</th></tr></thead><tbody><?php foreach($links as $x):?><tr><td>#<?=e($x['reservation_id'])?></td><td>#<?=e($x['payment_id'])?></td><td><?=e($x['payment_status_code'])?></td><td><?=e($x['payment_amount'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Current flight-leg links</h2><div class="tablewrap"><table><thead><tr><th>Reservation</th><th>Leg</th><th>Flight</th><th>Route</th></tr></thead><tbody><?php foreach($legLinks as $x):?><tr><td>#<?=e($x['reservation_id'])?></td><td>#<?=e($x['leg_id'])?></td><td><?=e($x['flight_number'])?></td><td><?=e($x['origin_airport_code'])?> → <?=e($x['destination_airport_code'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script>const kind=document.getElementById('kind'),linked=document.getElementById('linked_id');function filterLinked(){for(const o of linked.options){if(o.value===''){o.hidden=false;continue}o.hidden=o.dataset.kind!==kind.value}linked.value=''}kind.addEventListener('change',filterLinked);filterLinked();</script></body></html>
